content:
:root {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: #0f172a;
  color: #f8fafc;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  overflow-x: hidden;
  overflow-y: auto;
  background: radial-gradient(circle at center, #1e293b 0%, #0f172a 100%);
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  padding: 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
}

.header {
  text-align: center;
  z-index: 10;
  margin-bottom: 0.5rem;
}

.title {
  font-size: 2.25rem;
  font-weight: 800;
  background: linear-gradient(135deg, #60a5fa 0%, #a78bfa 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.5rem;
  letter-spacing: -0.025em;
}

.instructions {
  font-size: 0.95rem;
  color: #94a3b8;
  max-width: 600px;
  margin: 0 auto;
}

.canvas-container {
  flex: 1;
  width: 100%;
  aspect-ratio: 16 / 9;
  max-height: 550px;
  min-height: 220px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  touch-action: none;
  border-radius: 1rem;
  background: rgba(30, 41, 59, 0.5);
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.3), 0 10px 10px -5px rgba(0, 0, 0, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.05);
  margin: 1rem 0;
  overflow: hidden;
}

.controls-panel {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  z-index: 10;
  margin-bottom: 1rem;
}

.btn {
  background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
  color: white;
  border: none;
  padding: 0.6rem 1.25rem;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 6px -1px rgba(59, 130, 246, 0.3);
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.btn:hover {
  background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);
  transform: translateY(-1px);
  box-shadow: 0 6px 8px -1px rgba(59, 130, 246, 0.4);
}

.btn:active {
  transform: translateY(0);
  box-shadow: 0 2px 4px -1px rgba(59, 130, 246, 0.3);
}

.footer {
  font-size: 0.85rem;
  color: #64748b;
  text-align: center;
  z-index: 10;
}

@media (max-width: 768px) {
  .app-container {
    padding: 0.75rem;
    justify-content: space-around;
  }

  .title {
    font-size: 1.5rem;
  }

  .instructions {
    font-size: 0.8rem;
    line-height: 1.4;
  }

  .canvas-container {
    min-height: 180px;
    max-height: 350px;
    margin: 0.5rem 0;
  }

  .controls-panel {
    gap: 0.5rem;
    margin-bottom: 0.5rem;
  }

  .btn {
    padding: 0.45rem 0.85rem;
    font-size: 0.8rem;
  }

  .footer {
    font-size: 0.75rem;
  }
}

import { useEffect, useRef } from 'react'
import * as THREE from 'three'

interface CubeCanvasProps {
  autoRotate?: boolean
  cubeColor?: string
  resetKey?: number
}

export default function CubeCanvas({ autoRotate = true, cubeColor = '#3b82f6', resetKey = 0 }: CubeCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const cubeRef = useRef<THREE.Mesh | null>(null)
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null)
  const isDraggingRef = useRef(false)
  const previousMousePositionRef = useRef({ x: 0, y: 0 })
  const rotationVelocityRef = useRef({ x: 0.005, y: 0.005 })

  // autoRotateの最新値を参照するためのref
  const autoRotateRef = useRef(autoRotate)
  useEffect(() => {
    autoRotateRef.current = autoRotate
  }, [autoRotate])

  // cubeColorの変更をマテリアルに直接反映
  useEffect(() => {
    if (cubeRef.current) {
      const material = cubeRef.current.material as THREE.MeshStandardMaterial
      if (material && material.color) {
        material.color.set(cubeColor)
      }
    }
  }, [cubeColor])

  // resetKeyの変更時に回転をリセット
  useEffect(() => {
    if (cubeRef.current) {
      cubeRef.current.rotation.set(0, 0, 0)
      cubeRef.current.quaternion.identity()
      rotationVelocityRef.current = { x: 0.005, y: 0.005 }
    }
  }, [resetKey])

  useEffect(() => {
    const container = containerRef.current
    if (!container) return

    // シーン、カメラ、レンダラーの初期化
    const scene = new THREE.Scene()

    const width = container.clientWidth
    const height = container.clientHeight
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000)
    camera.position.z = 5

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true })
    renderer.setSize(width, height)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    container.appendChild(renderer.domElement)
    rendererRef.current = renderer

    // ライティング
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7)
    scene.add(ambientLight)

    const pointLight = new THREE.PointLight(0xffffff, 1.5)
    pointLight.position.set(5, 5, 5)
    scene.add(pointLight)

    const pointLight2 = new THREE.PointLight(0x60a5fa, 1)
    pointLight2.position.set(-5, -5, -5)
    scene.add(pointLight2)

    // キューブの作成
    const geometry = new THREE.BoxGeometry(2, 2, 2)

    const material = new THREE.MeshStandardMaterial({
      color: cubeColor,
      roughness: 0.3,
      metalness: 0.2,
      wireframe: false,
    })

    const cube = new THREE.Mesh(geometry, material)
    scene.add(cube)
    cubeRef.current = cube

    // エッジ（枠線）の追加
    const edges = new THREE.EdgesGeometry(geometry)
    const lineMaterial = new THREE.LineBasicMaterial({ color: 0xffffff, linewidth: 2 })
    const wireframe = new THREE.LineSegments(edges, lineMaterial)
    cube.add(wireframe)

    // アニメーションループ
    let animationFrameId: number

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate)

      if (cubeRef.current) {
        if (autoRotateRef.current && !isDraggingRef.current) {
          const qX = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), 0.005)
          const qY = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), 0.008)
          cubeRef.current.quaternion.multiplyQuaternions(qX, cubeRef.current.quaternion)
          cubeRef.current.quaternion.multiplyQuaternions(qY, cubeRef.current.quaternion)
        } else if (!isDraggingRef.current) {
          // 慣性による減衰
          rotationVelocityRef.current.x *= 0.95
          rotationVelocityRef.current.y *= 0.95

          const qX = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), rotationVelocityRef.current.x)
          const qY = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), rotationVelocityRef.current.y)
          cubeRef.current.quaternion.multiplyQuaternions(qX, cubeRef.current.quaternion)
          cubeRef.current.quaternion.multiplyQuaternions(qY, cubeRef.current.quaternion)
        }
      }

      renderer.render(scene, camera)
    }

    animate()

    // リサイズハンドラー
    const handleResize = () => {
      if (!container) return
      const w = container.clientWidth
      const h = container.clientHeight
      camera.aspect = w / h
      camera.updateProjectionMatrix()
      renderer.setSize(w, h)
    }

    window.addEventListener('resize', handleResize)

    // クリーンアップ
    return () => {
      window.removeEventListener('resize', handleResize)
      cancelAnimationFrame(animationFrameId)
      if (renderer.domElement && container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement)
      }
      geometry.dispose()
      material.dispose()
      lineMaterial.dispose()
      edges.dispose()
      renderer.dispose()
    }
  }, [])

  // マウス・タッチ操作イベントハンドラー
  const handlePointerDown = (e: React.PointerEvent) => {
    isDraggingRef.current = true
    previousMousePositionRef.current = {
      x: e.clientX,
      y: e.clientY,
    }
    ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
  }

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDraggingRef.current || !cubeRef.current) return

    const deltaX = e.clientX - previousMousePositionRef.current.x
    const deltaY = e.clientY - previousMousePositionRef.current.y

    rotationVelocityRef.current = {
      x: deltaY * 0.005,
      y: deltaX * 0.005,
    }

    const qX = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), rotationVelocityRef.current.x)
    const qY = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), rotationVelocityRef.current.y)
    cubeRef.current.quaternion.multiplyQuaternions(qX, cubeRef.current.quaternion)
    cubeRef.current.quaternion.multiplyQuaternions(qY, cubeRef.current.quaternion)

    previousMousePositionRef.current = {
      x: e.clientX,
      y: e.clientY,
    }
  }

  const handlePointerUp = (e: React.PointerEvent) => {
    isDraggingRef.current = false
    try {
      ;(e.target as HTMLElement).releasePointerCapture(e.pointerId)
    } catch {
      // キャプチャ解除のエラーは無視
    }
  }

  return (
    <div
      className="canvas-container"
      ref={containerRef}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      style={{ cursor: 'grab' }}
    />
  )
}

import { useState } from 'react'
import CubeCanvas from './CubeCanvas'
import './index.css'

export default function App() {
  const [autoRotate, setAutoRotate] = useState(true)
  const [colorIndex, setColorIndex] = useState(0)
  const [resetKey, setResetKey] = useState(0)
  const [message, setMessage] = useState<string | null>(null)

  const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899']

  const showFeedback = (msg: string) => {
    setMessage(msg)
    setTimeout(() => {
      setMessage(null)
    }, 2000)
  }

  const toggleAutoRotate = () => {
    setAutoRotate((prev) => {
      const next = !prev
      showFeedback(next ? '自動回転を開始しました' : '自動回転を停止しました')
      return next
    })
  }

  const changeColor = () => {
    setColorIndex((prev) => {
      const next = (prev + 1) % colors.length
      showFeedback('カラーを変更しました')
      return next
    })
  }

  const handleReset = () => {
    setResetKey((prev) => prev + 1)
    // ユーザーの自動回転設定を上書きしないよう、setAutoRotate(true)を削除
    showFeedback('位置をリセットしました')
  }

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">3D インタラクティブ 立方体</h1>
        <p className="instructions">
          マウスまたは指でドラッグして立方体を自由に回転させることができます。下のボタンから色や回転を切り替えられます。
        </p>
      </header>

      <div style={{ position: 'relative', width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
        {message && (
          <div style={{
            position: 'absolute',
            top: '10px',
            background: 'rgba(59, 130, 246, 0.9)',
            color: 'white',
            padding: '0.4rem 1rem',
            borderRadius: '0.5rem',
            fontSize: '0.85rem',
            zIndex: 20,
            boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.2)',
            pointerEvents: 'none'
          }}>
            {message}
          </div>
        )}
        <CubeCanvas
          autoRotate={autoRotate}
          cubeColor={colors[colorIndex]}
          resetKey={resetKey}
        />
      </div>

      <div className="controls-panel">
        <button className="btn" onClick={toggleAutoRotate}>
          {autoRotate ? '自動回転を停止' : '自動回転を開始'}
        </button>
        <button className="btn" onClick={changeColor}>
          カラー変更
        </button>
        <button className="btn" onClick={handleReset}>
          位置をリセット
        </button>
      </div>

      <footer className="footer">
        <p>Powered by React & Three.js</p>
      </footer>
    </div>
  )
}
